import{a as e}from"./chunk-2RJSKV3I.js";import{a as n}from"./chunk-AAOR4NZ4.js";import"./chunk-U37H3HIF.js";var a=e(n,["학생 이름 가리기","입력된 이름과 직접 그린 가림 상자는 검게 칠해져요. 손으로 쓴 이름은 따로 가림 상자를 그려야 해요.","내보내지 못함: {list}. 나머지는 내려받았어요.",{one:"파일 이름은 “{name}”이 돼요.",other:"파일 이름은 “{name}”이 되고, {n}개가 ZIP 하나에 담겨요."},"먼저 상, 중, 하 답안지를 고르세요","기준 답안지","기준 답안지","이걸 {lv} 기준 답안지로 지정","파일을 만드는 중…","{who} 대신 이걸 {lv} 답안지로 지정","다른 답안지 대신 이걸 {lv} 답안지로 지정","{lv}(내보낼 페이지 없음)","아직 고르지 않음","{lv} 답안지예요. 다시 클릭하면 해제돼요.","기준 답안지 내보내기","채점하면서 상\xB7중\xB7하 답안지를 고르세요: 점수 아래에서 상, 중, 하를 클릭합니다.","이름은 답안지에 있는 그대로 남아요.","기준 답안지 {n}개를 ZIP 하나로 저장했어요.","“{name}”을(를) 저장했어요.","{lv} 기준 답안지예요. 돌려주기에 있어서 바로 내보낼 수 있어요.","학교에서 총괄 평가마다 보관하는 상\xB7중\xB7하 답안지예요. 돌려주기에서 세 개 모두를 이름이 있는 것과 이름을 가린 것으로 내보내요.","문제가 생겼어요: {e}","의견란에 이미 있는 내용 아래에 추가(체크를 해제하면 바꾸기)","의견란에 넣기","그 ZIP을 열 수 없어요","코드","피드백","피드백","{ai}에서 가져오기","학생과 짝짓기","학생 {of}명 중 {n}명을 짝지었어요.",{one:"아직 피드백이 없는 제출물 1개:",other:"아직 피드백이 없는 제출물 {n}개:"},"{ai}에 이것들을 부탁하는 메모 복사","같은 형식으로 다음 코드의 피드백을 이어서 써 주세요: {codes}","복사했어요. {ai}에 붙여 넣으세요.",{one:"답변 1개에 아직 [name]이 남아 있어요. 의견란에서 학생 이름으로 바꾸거나 빼세요.",other:"답변 {n}개에 아직 [name]이 남아 있어요. 의견란에서 학생 이름으로 바꾸거나 빼세요."},"아직 코드를 찾지 못했어요. 각 블록은 S-7QK4 같은 코드로 시작해야 해요.",{one:"코드 1개가 이 과제에 속하지 않아요.",other:"코드 {n}개가 이 과제에 속하지 않아요."},"이 과제에 없음","파일 열기…","학생별 폴더로 제출물 다운로드",{one:"코드로 이름 붙은 제출물 1개를 학생별 폴더로 다시 정리할 수 있어요.",other:"코드로 이름 붙은 제출물 {n}개를 학생별 폴더로 다시 정리할 수 있어요."},"{ai}의 답변",{one:"의견란 1개에 피드백을 넣었어요.",other:"의견란 {n}개에 피드백을 넣었어요."},"넣기 전에 한번 읽어 보세요.","{ai}의 답변을 여기에 붙여 넣거나, 받은 파일(CSV, 텍스트, ZIP)을 여세요. 각 코드는 이 브라우저 안에서 학생과 짝지어져요.","학생","{ai}에서 받음 - {name}","평균","숫자를 띄어서 입력하세요. 예: 4 3.5 3",{one:"평균 {a}, 합계 {s}, 숫자 {n}개",other:"평균 {a}, 합계 {s}, 숫자 {n}개"},"마지막 글자 지우기","지우기","계산기 닫기","기록 지우기","기록","답이 여기에 보여요.","만점","점수를 백분율로","점수를 입력하면 백분율이 보여요.","{p}% ({s}%)","성적 척도로 {p}%, 그대로 {s}%","입력하거나 탭하세요. 예: 3.5+4+3","점수","점수 스티커","답안지에서 붙일 곳을 클릭하세요","스티커: {s}","계산식","계산기","점수로 쓰기","이 숫자를 열려 있는 학생의 점수 칸에 넣어요","점수를 {n}(으)로 정했어요","전체 {n}","모든 답안지를 확인했어요","뒤로",{one:"상자 {n}개",other:"상자 {n}개"},"이 페이지를 보여 줄 수 없어요.","답안지 {n}/{of}","아직 이 답안지를 그리는 중이에요","마지막 상자를 모든 답안지에 적용","모든 답안지를 확인했어요.",{one:"그 가림을 답안지 {n}개에 더 추가했어요",other:"그 가림을 답안지 {n}개에 더 추가했어요"},"답안지 찾기","표시됨 {n}","이름 위로 드래그하면 가려져요. 상자를 클릭하면 빠져요. {key}로 실행 취소해요.","마지막 답안지였어요","“{q}”와(과) 일치하는 학생이 없어요.","확인할 PDF나 그림이 없어요","아직 확인 안 함","되돌릴 것이 없어요","보여 줄 것이 없어요.","확인함","제출물","{of}개 중 {n}개 확인","가림이 잘 됐어요","가림이 잘 됐어요, 완료",", 아직 확인 안 함",", 확인함","가림 확인","미확인 {n}","가림을 뺐어요. {key}를 누르면 되돌려요.","미확인으로 표시","약 {v}","{n}개는 도우미에게서 가져온 피드백처럼 한꺼번에 바뀌어서 순서를 알 수 없어요","뒤로","이 페이지를 그릴 수 없어요.","매긴 순서대로의 점수입니다. 같은 점수가 차트 아래 목록에도 있습니다.","{who}, {v}/{max}점, {n}개 중 {k}번째로 채점","답안지가 너무 적어 말할 수 없습니다.","채점이 엄격해졌는지 너그러워졌는지 말하려면 적어도 {n}이(가) 필요해요. 그보다 적으면 보이는 패턴은 대부분 우연이에요.",{one:"지금까지 시간 기록이 있는 답안지는 {n}개뿐이에요.",other:"지금까지 시간 기록이 있는 답안지는 {n}개뿐이에요."},"지금까지 시간 기록이 있는 답안지가 없어요.","처음 채점","각 점수가 마지막으로 바뀐 시점을 기준으로 하므로, 나중에 다시 본 답안지는 늦은 것으로 칩니다. 확정된 점수만.","채점하면서 더 엄격해지거나 너그러워졌나요?","같은 점수, 나란히",{one:"뒤쪽 답안지의 점수가 약 {n}점 높았어요.",other:"뒤쪽 답안지의 점수가 약 {n}점 높았어요."},"답안지가 {n}개면 이건 우연일 가능성이 커요.","그럴 수도 있지만, 아직 판단하기엔 일러요.","마지막 채점","제외됨: {list}.","답안지 {n}개에서 우연히 생기는 차이보다 커요.","한번 살펴볼 만해요.","목록으로 보기",{one:"뒤쪽 답안지의 점수가 약 {n}점 낮았어요.",other:"뒤쪽 답안지의 점수가 약 {n}점 낮았어요."},{one:"{n}장",other:"{n}장"},"다음 페이지","답안지가 없어요.","여기 보여 줄 PDF나 그림이 없어요. 답안지를 열어서 읽으세요.",{one:"{n}개는 시간 기록이 없어요(앱이 기록을 시작하기 전에 채점했거나, 답안지에서 읽어 온 것)",other:"{n}개는 시간 기록이 없어요(앱이 기록을 시작하기 전에 채점했거나, 답안지에서 읽어 온 것)"},"이 정도 차이는 우연히 자주 생겨요.","답안지가 {n}개뿐이면 큰 변화만 드러나요. 그래서 채점이 일정했다고 단정할 수는 없어요.","뚜렷한 변화가 없어요.","확정된 점수가 같은 답안지가 아직 없습니다.","처음 {k}개는 평균 약 {a}점, 마지막 {k}개는 약 {b}점이에요({max}점 만점).","순서","{b}페이지 중 {a}페이지","답안지","점수를 고르면 그 답안지들을 나란히 볼 수 있어요.","이전 페이지","시간 기록이 있는 답안지가 너무 적음",{one:"뒤쪽 답안지가 약 {n}점 높음",other:"뒤쪽 답안지가 약 {n}점 높음"},{one:"뒤쪽 답안지가 약 {n}점 낮음",other:"뒤쪽 답안지가 약 {n}점 낮음"},"뚜렷한 변화 없음","답안지가 {n}개보다 적으면 루브릭 항목을 하나씩 분석하지 않아요. 항목 하나만으로는 오차가 너무 커요.","{v}점 받은 답안지","점수","채점됨","답안지가 하나뿐인 점수는 목록에 없어요.","학생","채점하면서 점점 너그러워졌을 수도 있고, 그냥 그 답안지들이 더 좋았을 수도 있어요. 점수가 같은 앞쪽과 뒤쪽 답안지를 몇 개 비교해 보세요.","채점하면서 점점 엄격해졌을 수도 있고, 그냥 그 답안지들이 더 약했을 수도 있어요. 점수가 같은 앞쪽과 뒤쪽 답안지를 몇 개 비교해 보세요.",{one:"확인할 답안지 {n}개: 답안지의 성적이 내 성적과 다르거나, 성적이 둘 이상이거나, 성적이 아닐 수도 있는 숫자가 있어요.",other:"확인할 답안지 {n}개: 답안지의 성적이 내 성적과 다르거나, 성적이 둘 이상이거나, 성적이 아닐 수도 있는 숫자가 있어요."},"모두 보기","이것만 보기","윗줄의 점수","성적이 없는 파일도 보기 (내려받는 성적표에도 같은 줄이 들어가요)","답안지에서 찾은 성적도 보기 (Grading Studio에서 준 점수가 항상 우선해요)","뒤로","이 파일에는 표시도 입력된 글자도 없어요. Kami에서 채점했다면 표시가 파일에 저장되지 않았을 수 있어요. '직접 상자로 표시'를 써 보세요.","직접 상자로 표시","상자 그림(다시 드래그하면 바뀌어요)","학생 {n}/{of} \xB7 답안지 {p}/{pof}","성적 주위로 드래그해 상자를 그리세요. 저장한 뒤 다음 답안지로 넘어가요. 왼쪽\xB7오른쪽 화살표로 앞뒤로 이동하고, Esc를 누르면 끝나요.","성적에 상자 그리기","직접 상자로 표시함","다시 포함","취소","이 파일을 읽을 수 없었어요","이 파일을 열 수 없어요. 건너뛰기를 클릭하세요.","확인할 것 {n}개","확인할 것 {n}개","{v} 복사함","클릭해서 복사","모든 점수 복사","그래도 복사",{one:"학생 {n}명은 루브릭의 일부만 채점되었습니다: {names}. 이 총점은 최종이 아니며 복사한 내용에 “(partial)”이 붙습니다. 그래도 복사할까요?",other:"학생 {n}명은 루브릭의 일부만 채점되었습니다: {names}. 이 총점은 최종이 아니며 복사한 내용에 “(partial)”이 붙습니다. 그래도 복사할까요?"},{one:"목록 순서대로 점수 {n}개를 복사했습니다(확실하지 않으면 비워 둠)",other:"목록 순서대로 점수 {n}개를 복사했습니다(확실하지 않으면 비워 둠)"},"외 {n}명","완료","각 성적을 직접 상자로 표시","답안지에는 다르게 적혀 있어요","{of}개 중 {n}개 피드백 완료","첫 페이지","표시는 있지만 입력된 글자가 없어서, 성적이 손글씨이거나 평면화되었을 수 있어요. '직접 상자로 표시'를 써 보세요.","답안지에서 찾음: {list}","'{text}'에서","각 줄은 그 학생 폴더 안에 있는, 줄에 적힌 파일로 만들어요. 그림을 클릭하면 그 학생이 열리고, 점수를 클릭하면 복사돼요.","이게 성적인가요?","마지막 답안지였어요","마지막 페이지","제외","제외됨 (표시 없음).","더 이상 면제로 표시되지 않음","더 이상 미제출로 표시되지 않음","각 답안지에서 성적을 찾는 중…","이 답안지에는 성적이 여러 개 있어요. 어느 것을 쓸지 고르세요.","성적 {n}개 찾음, 확인하세요","아직 성적 없음.","이 답안지에는 아직 점수 도장이 없어요. 총점 옆의 '도장'으로 점수를 찍으세요.","상자로 표시할 답안지가 없어요","고를 답안지가 없어요","아직 찾은 성적 없음","성적 아님","아직 형광펜으로 표시하지 않은 기준이 있어요","제출한 것 없음","채점하지 않은 파일만 있음, 제외됨","이 학생 열기",{one:"파일 {n}개에 표시가 없어서 여분의 답안지로 보고 제외했어요.",other:"파일 {n}개에 표시가 없어서 여분의 답안지로 보고 제외했어요."},"숨기기","보기","{p}페이지","답안지에","(일부)","읽은 값","답안지에서 {n}개 읽음","직접 상자로 표시함 \xB7 다시 하기","'{v}'은(는) 성적이 아니라고 정했어요.","'{v}'을(를) 성적으로 정했어요.","점수","{of}개 중 {n}개 채점됨","입력된 글자에서 성적을 찾지 못했어요: '{text}'","성적표","건너뛰기(성적 없음)","모든 답안지에서 같은 위치","공통 위치 바꾸기","성적을 적는 곳 주위로 드래그해 상자를 그리세요. 모든 답안지에서 같은 위치를 잘라 내서, 손으로 쓴 성적도 찾아요.","공통 위치 그만 쓰기","모든 답안지에서 같은 위치","페이지","성적 위치 고르기","이 위치 사용","표","각 부분을 내 표시만 남게 자르기","보이는 대로 입력","그림에 보이는 점수를 입력하세요","입력된 글자: '{text}'","입력된 글자: '{text}' \xB7 {p}페이지","실행 취소","이걸로 쓰기","성적 보기","폴더와 파일","Word 파일","Word 루브릭","Word 파일을 준비하는 중…","내가 준 점수","Grading Studio에서 내가 준 점수: {v}","내가 준 점수 (일부)","내가 준 점수 (반영되는 시도)","가림 확인…",{one:"답안지 {of}개 중 {n}개 확인했어요.",other:"답안지 {of}개 중 {n}개 확인했어요."},"답안지를 세는 중…","가림 확인에서 이름 위로 드래그해 상자를 그린 다음, 모든 답안지에 적용하세요.","먼저 이름을 가리세요.",{one:"이것부터 확인하세요:",other:"이것들부터 확인하세요:"},"이름을 찾는 중…","확인할 PDF나 그림이 없어요.","이름이 다시 보여요","이름 숨김: 답안지는 무작위 순서, 이름은 가려짐","답안지는 답안지 1, 답안지 2…처럼 무작위 순서로 보여요. 점수는 그대로 맞는 학생에게 들어가요.","새로 섞고 시작","섞었어요: 새로운 무작위 순서","이름 숨기기 시작","이름 숨기기",{one:"이 Word 답안지에는 이름이 보여요.",other:"이 Word 답안지들에는 이름이 보여요."},{one:"이 답안지에 이름이 보일 수 있어요.",other:"이 답안지들에 이름이 보일 수 있어요."},{one:"가리려면 PDF 페이지로 바꾸세요.",other:"가리려면 PDF 페이지로 바꾸세요."},"일관성","개요","분석 보기","이 과제에서 채점할 평가 기준을 체크하세요. 각각 0부터 {top}까지 점수를 매기는 항목이 돼요. 과제 하나는 보통 두세 개를 평가해요.","{cls}은(는) MYP 평가 기준으로 채점해요.","취소","이 과제의 평가 기준 고르기","평가 기준","이 과제가 평가하는 기준: {list}","수준, 0부터 {top}까지",{one:"답안지 {n}개에 이미 준 수준이나 점수가 사라져요. 실행 취소로 되돌릴 수 있어요.",other:"답안지 {n}개에 이미 준 수준이나 점수가 사라져요. 실행 취소로 되돌릴 수 있어요."},"평가 기준 {of}개 중 {n}개 채점함","항목의 각 수준이 무슨 뜻인지는 직접 써요. 나중에 루브릭 설정에서 내 기술어를 붙여 넣으세요.","평가 기준을 하나 이상 체크하세요","저장","도장","답안지에 수준 찍기: {text}","이 과제가 평가하는 기준","다시 묻기","확인할 것 {n}개","확인해 주기 전까지 점수는 숨겨져요.","{cls}에서","이전 {n}개","이전 {n}개 \xB7 최근 {pct}","“{name}”은(는) 이 학생이 아니라고 정했어요.","일치 없음","앱에 점수가 없어요. 답안지에는 있을 수 있어요.","다른 학생","이 이름은 {cls} 명단과 확실히 일치하지 않아서, 이전 과제를 확실하게 연결할 수 없어요.","이 다운로드에는 명단이 선택되지 않아서, 이전 과제를 확실하게 연결할 수 없어요.","답안지에","일부","“{name}”","같은 학생","면제","지각","미제출","이전 과제","실행 취소","{where}에 있어요.","다운로드 {n}개","이름이 비슷하지만 확실히 일치하지는 않아요.","이름은 같지만 확인할 명단이 없어요.","이름은 같지만 {cls}에 있어요. 다른 사람일 수 있어요.","“{name}”이(가) 이 학생이라고 정했어요.","{ai}에 할 말","{ai}에서 가져오기","가림 확인","가림 다시 확인","나머지 {n}개 확인","{of}개 중 {n}개 확인","복사했어요. ZIP과 함께 {ai}에 붙여 넣으세요.","메시지 복사","복사하지 못했어요. 텍스트를 선택해 직접 복사하세요.","확인함({n})","{ai}와(과) 공유","{ai}에 줄 것","완료했어요. ZIP을 {ai}에 준 다음, 보내온 내용을 '가져오기'로 불러오세요.","{when}에 만듦.",{one:"{when}에 만듦. 확인 안 한 제출물이 1개 있어요.",other:"{when}에 만듦. 확인 안 한 제출물이 {n}개 있어요."},"이름을 가리고 사진 만드는 중 {n}/{of}","표시만","도우미와 공유","복사했어요. 표시 파일과 함께 {ai}에 붙여 넣으세요.","표시 파일 다운로드",{one:"완료: 학생 1명. 메시지와 함께 파일을 {ai}에 주세요.",other:"완료: 학생 {n}명. 메시지와 함께 파일을 {ai}에 주세요."},"표시 파일을 내려받으세요.","학생 피드백을 써 줬다면 답변을 가져오세요.","반 전체의 경향을 살펴보는 파일로, 이름은 들어 있지 않아요. 학생에게는 ZIP과 같은 코드가 붙고, 의견 속 이름은 [name]이 돼요. 제출물은 보내지 않으니 가림을 확인할 필요가 없어요.","의견과 페이지 위 텍스트","펜 표시와 체크 개수","루브릭 점수, 총점, 백분율, 상태","교정 부호와 스티커","형광펜을 칠하거나 동그라미를 치거나 의견을 단 단어","{ai} 열기",{one:"ZIP에 없음: 넣을 수 있는 제출물이 없는 학생 1명.",other:"ZIP에 없음: 넣을 수 있는 제출물이 없는 학생 {n}명."},"답안지와 표시","표시 읽는 중 {n}/{of}","가림을 확인하세요.","이름마다 위로 드래그해 상자를 그리세요. 이름이 모두 같은 자리에 있으면 한 번만 그려서 모든 제출물에 쓸 수 있어요.","ZIP을 내려받으세요.","이 메시지와 함께 {ai}에 주세요. 내용은 마음대로 바꿔도 돼요.","답변을 가져오세요.","이름이 없는 ZIP을 만들어 {ai}에 줄 수 있어요. 학생마다 무작위 코드가 붙고, 누가 누구인지 목록은 이 브라우저에만 남아요.","{ai}에 줄 때까지 내 컴퓨터에만 있어요.","아직 확인 안 함({n})","모든 페이지가 그림이 되어서, 숨은 글이나 파일 정보는 같이 가지 않아요.","가림 확인에서 상자를 그린 곳의 이름은 가려져요.","페이지에 입력된 이름은 어디에 있든 검게 가려져요. 이메일 주소와 긴 ID 번호도 마찬가지예요.","점수, 루브릭, 의견도 함께 가고, 이름은 [name]으로 바뀌어요.","PDF와 사진만 들어가요. Word 파일은 PDF 페이지로 바꾸기 전에는 들어가지 않아요.","들어가는 것","문제가 생겼어요: {e}","{ai}용 ZIP 다운로드","그래도 ZIP 다운로드","취소","그림을 복사했어요. 필요한 곳에 붙여 넣으세요.","복사하기","복사할 부분을 끌어서 고르세요.","복사할 부분을 끌어서 고르거나, 페이지를 클릭해 전체를 복사하세요.","Esc","좋은 예시로 저장","그림을 만들 수 없었어요. 더 작은 영역으로 해 보세요.","내 표시 포함","복사할 영역을 끌어서 고르세요.","영역을 끌어서 고르거나 페이지를 클릭하세요.","모든 것이 화면에 보이는 그대로예요.","답안지에서는 이름 가리기 부분이 칠해지고, 학생 이름과 파일 이름은 빠져요. 나머지는 화면에 보이는 그대로예요.","이 브라우저는 그림을 복사할 수 없어서 Screenshot.png로 저장했어요.","그다음","스크린샷","전체 화면","화면에 보이는 모든 것 (Enter)","관찰 목록에 추가","저장한 코멘트","아직 저장한 코멘트가 없어요. 코멘트 아래에서 저장하거나 설정 > 채점에서 추가하세요."],null);export{a as default};
